def fix_multiple_active_tos(apps, schema_editor):
    """
    Fix any offerings that have multiple active ToS configurations.
    Keep only the most recent one active, deactivate the rest.
    """
    OfferingTermsOfService = apps.get_model("marketplace", "OfferingTermsOfService")

    offerings_with_multiple_active = (
        OfferingTermsOfService.objects.filter(is_active=True)
        .values("offering")
        .annotate(active_count=Count("id"))
        .filter(active_count__gt=1)
    )

    # Get all offering ids with multiple active ToS configurations
    all_offering_ids = [val["offering"] for val in offerings_with_multiple_active]

    # Get all active ToS configurations for the offerings
    all_active_tos = OfferingTermsOfService.objects.filter(
        offering__in=all_offering_ids, is_active=True
    ).order_by("-created")

    tos_by_offering = {}

    for tos in all_active_tos:
        if tos.offering_id not in tos_by_offering:
            tos_by_offering[tos.offering_id] = []
        tos_by_offering[tos.offering_id].append(tos)

    tos_ids_to_deactivate = set()

    for tos_list in tos_by_offering.values():
        to_deactivate = tos_list[1:]
        tos_ids_to_deactivate.update([tos.id for tos in to_deactivate])

    logger.info(f"Deactivating {len(tos_ids_to_deactivate)} ToS configurations")

    # Bulk update the ToS configurations to inactive
    OfferingTermsOfService.objects.filter(id__in=tos_ids_to_deactivate).update(
        is_active=False
    )


